#include <string>
#include <vector>
#include <unordered_map>

class Solution {
public:
    std::string evaluate(std::string s, std::vector<std::vector<std::string>>& knowledge) {
        std::unordered_map<std::string, std::string> dict;
        dict.reserve(knowledge.size());
        for (const auto& pair : knowledge) {
            dict[pair[0]] = pair[1];
        }

        std::string result;
        result.reserve(s.size());
        std::string current_key;
        bool in_bracket = false;

        for (char c : s) {
            if (c == '(') {
                in_bracket = true;
                current_key.clear();
            } else if (c == ')') {
                in_bracket = false;
                auto it = dict.find(current_key);
                if (it != dict.end()) {
                    result += it->second;
                } else {
                    result += '?';
                }
            } else {
                if (in_bracket) {
                    current_key += c;
                } else {
                    result += c;
                }
            }
        }

        return result;
    }
};
